import React, { useEffect, useState } from "react";
import axios from "axios";
import AdminSidebar from "../components/AdminSidebar";

function AdminUsers() {
  const [users, setUsers] = useState([]);

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = async () => {
    const token = localStorage.getItem("adminToken");

    const res = await axios.get(
      "http://localhost:5000/api/admin/users",
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );

    setUsers(res.data);
  };

  return (
    <>
      <AdminSidebar />

      <div style={{ marginLeft: "270px", padding: "28px", background: "linear-gradient(180deg, #f8fafc 0%, #ffffff 55%)", minHeight: "calc(100vh - 64px)" }}>
        <div style={{ marginBottom: 18 }}>
          <h1 style={{ margin: 0, fontSize: 26, color: "#0f172a" }}>Users</h1>
          <div style={{ marginTop: 6, color: "#64748b", fontWeight: 600 }}>Registered accounts</div>
        </div>

        <table style={{ width: "100%", borderCollapse: "separate", borderSpacing: 0, overflow: "hidden", borderRadius: 14, border: "1px solid rgba(15,23,42,0.08)" }}>
          <thead>
            <tr style={{ background: "#f1f5f9" }}>
              <th style={{ textAlign: "left", padding: "12px 14px", color: "#334155", fontSize: 13 }}>Name</th>
              <th style={{ textAlign: "left", padding: "12px 14px", color: "#334155", fontSize: 13 }}>Email</th>
              <th style={{ textAlign: "left", padding: "12px 14px", color: "#334155", fontSize: 13 }}>Role</th>
              <th style={{ textAlign: "left", padding: "12px 14px", color: "#334155", fontSize: 13 }}>Language</th>
            </tr>
          </thead>

          <tbody>
            {users.map((u) => (
              <tr key={u._id} style={{ background: "white" }}>
                <td style={{ padding: "12px 14px", borderTop: "1px solid rgba(15,23,42,0.06)", color: "#0f172a" }}>{u.name}</td>
                <td style={{ padding: "12px 14px", borderTop: "1px solid rgba(15,23,42,0.06)", color: "#0f172a" }}>{u.email}</td>
                <td style={{ padding: "12px 14px", borderTop: "1px solid rgba(15,23,42,0.06)", color: "#0f172a" }}>{u.role}</td>
                <td style={{ padding: "12px 14px", borderTop: "1px solid rgba(15,23,42,0.06)", color: "#0f172a" }}>{u.language}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}

export default AdminUsers;