import React, { useEffect, useState } from "react";
import axios from "axios";
import AdminLayout from "../components/AdminLayout";
import AdminAnalyticsCharts from "./AdminAnalyticsCharts";

function AdminDashboard() {
  const [stats, setStats] = useState({});

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const res = await axios.get("http://localhost:5000/api/admin/stats", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      setStats(res.data);
      console.log("Admin stats response:", res.data);
    } catch (err) {
      console.log("Admin stats error:", {
        message: err?.message,
        status: err?.response?.status,
        data: err?.response?.data,
      });
    }
  };

  return (
    <AdminLayout title="Admin Dashboard" subtitle="Overview">
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit,minmax(210px,1fr))",
          gap: "16px",
        }}
      >
        <Card title="Total" value={stats.total} />
        <Card title="Pending" value={stats.pending} />
        <Card title="In Progress" value={stats.inProgress} />
        <Card title="Resolved" value={stats.resolved} />
        <Card title="Verified" value={stats.verified} />
        <Card title="Fake" value={stats.fake} />
        <Card title="Flagged" value={stats.flagged} />

        {/* Analytics / charts section */}
        <div
          style={{
            gridColumn: "1 / -1",
            marginTop: 8,
            color: "#64748b",
            fontWeight: 700,
            fontSize: 13,
          }}
        >
          Analytics
        </div>
        <div
          style={{ gridColumn: "1 / -1", display: "flex", gap: 16, flexWrap: "wrap" }}
        >
          <Card title="Avg. Votes" value={stats.avgVotes} />
          <Card
            title="Avg. Response (days)"
            value={
              stats?.avgResponseMs != null
                ? Math.round((Number(stats.avgResponseMs) || 0) / (1000 * 60 * 60 * 24))
                : 0
            }
          />
          <Card title="Top Category" value={stats.topCategoryCount} />
        </div>

        <AdminAnalyticsCharts stats={stats} />
      </div>
    </AdminLayout>
  );
}

function Card({ title, value }) {
  return (
    <div
      style={{
        background: "white",
        padding: "18px 18px",
        borderRadius: "16px",
        boxShadow: "0 10px 25px rgba(2,6,23,0.08)",
        border: "1px solid rgba(15,23,42,0.06)",
      }}
    >
      <div style={{ color: '#64748b', fontWeight: 700, marginBottom: 8, fontSize: 13 }}>
        {title}
      </div>
      <div style={{ fontSize: 30, fontWeight: 900, color: '#0f172a' }}>
        {value || 0}
      </div>
    </div>
  );
}

export default AdminDashboard;