import React from "react";
import AdminSidebar from "./AdminSidebar";

function AdminLayout({ title, children, subtitle }) {
  return (
    <>
      <AdminSidebar />
      <div
        style={{
          marginLeft: 270,
          padding: 28,
          background: "linear-gradient(180deg, #f8fafc 0%, #ffffff 55%)",
          minHeight: "calc(100vh - 64px)",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            justifyContent: "space-between",
            gap: 16,
            marginBottom: 18,
          }}
        >
          <div>
            <h1 style={{ margin: 0, fontSize: 28, color: "#0f172a" }}>{title}</h1>
            {subtitle ? (
              <div style={{ marginTop: 6, color: "#64748b", fontWeight: 600 }}>
                {subtitle}
              </div>
            ) : null}
          </div>
        </div>
        {children}
      </div>
    </>
  );
}

export default AdminLayout;

