import React, { useEffect, useState } from "react";
import axios from "axios";
import AdminSidebar from "../components/AdminSidebar";

function AdminVerification() {
  const [complaints, setComplaints] = useState([]);

  useEffect(() => {
    loadComplaints();
  }, []);

  const loadComplaints = async () => {
    const token = localStorage.getItem("adminToken");

    const res = await axios.get(
      "http://localhost:5000/api/admin/complaints",
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );

    setComplaints(res.data);
  };

  const verifyComplaint = async (id, status) => {
    const token = localStorage.getItem("adminToken");

    await axios.put(
      `http://localhost:5000/api/admin/complaints/${id}/verify`,
      {
        verificationStatus: status,
      },
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );

    loadComplaints();
  };

  return (
    <>
      <AdminSidebar />

      <div
        style={{
          marginLeft: "270px",
          padding: "28px",
          background: "linear-gradient(180deg, #f8fafc 0%, #ffffff 55%)",
          minHeight: "calc(100vh - 64px)",
        }}
      >
        <div style={{ marginBottom: 18 }}>
          <h1 style={{ margin: 0, fontSize: 26, color: "#0f172a" }}>Verification Center</h1>
          <div style={{ marginTop: 6, color: "#64748b", fontWeight: 600 }}>
            Review and verify complaints
          </div>
        </div>

        <div style={{ display: "grid", gap: 14 }}>
          {complaints.map((c) => (
            <div
              key={c._id}
              style={{
                background: "#ffffff",
                borderRadius: 14,
                border: "1px solid rgba(15,23,42,0.08)",
                padding: 16,
                boxShadow: "0 10px 25px rgba(2,6,23,0.05)",
              }}
            >
              <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 14 }}>
                <div>
                  <h3 style={{ margin: 0, fontSize: 16, color: "#0f172a" }}>{c.category}</h3>
                  <div style={{ marginTop: 6, color: "#64748b", fontWeight: 600 }}>{c.location}</div>
                </div>

                <div style={{ textAlign: "right" }}>
                  <div style={{ fontSize: 12, color: "#64748b", fontWeight: 700 }}>Verification</div>
                  <div style={{ fontSize: 14, fontWeight: 900, color: "#0f172a" }}>
                    {(() => {
                      const vs = c.verification?.status;
                      if (vs === "Verified") return "Verified";
                      if (vs === "Fake") return "Rejected";
                      return (vs || c.status || "—").toString();
                    })()}

                  </div>

                </div>
              </div>

              <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 14 }}>
                <button
                  onClick={() => verifyComplaint(c._id, "Verified")}
                  style={{
                    padding: "10px 14px",
                    borderRadius: 10,
                    border: "1px solid rgba(34,197,94,0.35)",
                    background: "rgba(34,197,94,0.08)",
                    color: "#16a34a",
                    cursor: "pointer",
                    fontWeight: 800,
                  }}
                >
                  Verify
                </button>

                <button
                  onClick={() => verifyComplaint(c._id, "Fake")}
                  style={{
                    padding: "10px 14px",
                    borderRadius: 10,
                    border: "1px solid rgba(220,38,38,0.35)",
                    background: "rgba(220,38,38,0.08)",
                    color: "#dc2626",
                    cursor: "pointer",
                    fontWeight: 800,
                  }}
                >
                  Mark Fake
                </button>

                <button
                  onClick={() => verifyComplaint(c._id, "Under Investigation")}
                  style={{
                    padding: "10px 14px",
                    borderRadius: 10,
                    border: "1px solid rgba(37,99,235,0.35)",
                    background: "rgba(37,99,235,0.08)",
                    color: "#2563eb",
                    cursor: "pointer",
                    fontWeight: 800,
                  }}
                >
                  Investigate
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </>
  );
}

export default AdminVerification;