import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import AdminSidebar from '../components/AdminSidebar';

function AdminLogin() {
  const navigate = useNavigate();


  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const res = await axios.post('http://localhost:5000/api/admin/login', {
        email: form.email,
        password: form.password,
      });

      // Backend returns { token, admin: {...} }
      localStorage.setItem('adminToken', res.data.token);
      localStorage.setItem('admin', JSON.stringify(res.data.admin || null));

      navigate('/admin');
    } catch (err) {
      setError(err.response?.data?.message || 'Admin login failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <AdminSidebar />
      <div
        style={{
          marginLeft: '270px',
          minHeight: 'calc(100vh - 64px)',
          padding: '32px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: 'linear-gradient(180deg, #f8fafc 0%, #ffffff 55%)',
        }}
      >
        <div
          style={{
            width: '100%',
            maxWidth: 440,
            background: '#fff',
            borderRadius: 16,
            boxShadow: '0 10px 25px rgba(2,6,23,0.08)',
            border: '1px solid rgba(15,23,42,0.06)',
            padding: 24,
          }}
        >
          <h2 style={{ margin: 0, color: '#0f172a', fontSize: 24 }}>Admin Login</h2>
          <div style={{ marginTop: 8, color: '#64748b', fontWeight: 600 }}>
            Access the admin dashboard
          </div>

          {error && (
            <div
              style={{
                marginTop: 14,
                background: '#FEE2E2',
                color: '#DC2626',
                padding: '10px 12px',
                borderRadius: 10,
                fontSize: 13,
                fontWeight: 700,
              }}
            >
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} style={{ marginTop: 18 }}>
            <label style={{ display: 'block', fontSize: 13, fontWeight: 700, color: '#374151', marginBottom: 6 }}>
              Email
            </label>
            <input
              name="email"
              type="email"
              value={form.email}
              onChange={handleChange}
              required
              style={{
                width: '100%',
                padding: 12,
                borderRadius: 10,
                border: '1px solid #D1D5DB',
                marginBottom: 14,
                boxSizing: 'border-box',
              }}
            />

            <label style={{ display: 'block', fontSize: 13, fontWeight: 700, color: '#374151', marginBottom: 6 }}>
              Password
            </label>
            <input
              name="password"
              type="password"
              value={form.password}
              onChange={handleChange}
              required
              style={{
                width: '100%',
                padding: 12,
                borderRadius: 10,
                border: '1px solid #D1D5DB',
                marginBottom: 18,
                boxSizing: 'border-box',
              }}
            />

            <button
              type="submit"
              disabled={loading}
              style={{
                width: '100%',
                padding: 12,
                borderRadius: 10,
                border: 'none',
                background: '#1A56DB',
                color: '#fff',
                fontWeight: 900,
                cursor: loading ? 'not-allowed' : 'pointer',
                opacity: loading ? 0.7 : 1,
              }}
            >
              {loading ? 'Logging in...' : 'Login'}
            </button>
          </form>

          <div style={{ marginTop: 14, fontSize: 12, color: '#6B7280', fontWeight: 600 }}>
            Enter admin credentials to access the dashboard.
          </div>

        </div>
      </div>
    </>
  );
}

export default AdminLogin;

